mapper.update:
UPDATE zhw_user
nick_name = #{nickName}, avatar = #{avatar}, remark = #{remark}, password = #{password}, update_time = NOW()
WHERE user_id = #{userId}

mapper.select:
SELECT u.*, COALESCE((SELECT SUM(score) FROM zhw_user_score WHERE user_id = u.user_id), 0) AS score, (SELECT COUNT(1) FROM zhw_story WHERE user_id = u.user_id AND del_flag = '0' AND status = '0') AS story_count, (SELECT COUNT(1) FROM zhw_branch WHERE user_id = u.user_id AND del_flag = '0') AS branch_count, (SELECT COUNT(1) FROM zhw_comment WHERE user_id = u.user_id AND del_flag = '0') AS comment_count, COALESCE((SELECT SUM(b.like_count) FROM zhw_branch b WHERE b.user_id = u.user_id AND b.del_flag = '0'), 0) AS like_count FROM zhw_user u
AND (u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%'))
AND u.status = #{status}
AND u.create_time >= #{beginTime}
AND u.create_time <= #{endTime}
ORDER BY score DESC ORDER BY story_count DESC ORDER BY branch_count DESC ORDER BY u.create_time ASC ORDER BY u.user_id DESC
